import json
from collections import Counter

workspace = "/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace"
program_dir = "/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs"
task_id = "task-607a9d08"

# Read test input
with open(f"{program_dir}/task-{task_id}_test.json", "r") as f:
    data = json.load(f)
test_input = data["input"]
h, w = len(test_input), len(test_input[0])

# Find all connected components
visited = set()
components = {}
def get_neighbors(r, c):
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        yield r+dr, c+dc

for r in range(h):
    for c in range(w):
        if (r, c) not in visited:
            color = test_input[r][c]
            q = [(r, c)]
            visited.add((r, c))
            pixels = [(r, c)]
            comp_idx = len(components)
            components[comp_idx] = {"color": color, "pixels": []}
            while q:
                curr = q.pop(0)
                nr, nc = curr
                for rr, cc in get_neighbors(nr, nc):
                    if 0 <= rr < h and 0 <= cc < w and (rr, cc) not in visited:
                        if test_input[rr][cc] == color:
                            visited.add((rr, cc))
                            pixels.append((rr, cc))
                            q.append((rr, cc))
            components[comp_idx]["pixels"].extend(pixels)

print(f"Total components: {len(components)}")

# Count pixels per color
for comp in sorted(components.values(), key=lambda x: -len(x["pixels"])):
    print(f"Color {comp['color']}: {len(comp['pixels'])} pixels")

# Determine background color (most frequent)
freq = Counter()
for r in range(h):
    for c in range(w):
        freq[test_input[r][c]] += 1
background = max(freq.keys(), key=lambda x: freq[x])
print(f"\nBackground color: {background} with count {freq[background]}")

